0347 | \begin{thm}[{see \cite[Theorem II.6.8]{bridson2011metric}}]\label{thm:bh-isom}
0348 | 	Let $X$ be a $\cato$ space. Let $\gamma$ be a hyperbolic isometry of $X$.
0349 | 	\begin{enumerate}[(1)]
0350 | 		\item\label{it:parallel-axes} The axes of $\gamma$ are parallel to each other an their union
0351 | 		is $\mathrm{Min}(\gamma)$.
0352 | 		\item\label{it:min-action} $\mathrm{Min}(\gamma)$ is isometric to a product
0353 | 		$Y\times\bbR$, and the restriction of $\gamma$ to
0354 | 		$\mathrm{Min}(\gamma)$ is of the form $(y,t)\mapsto
0355 | 		(y,t+|\gamma|)$, where $y \in Y, t \in \bbR$.
0356 | 		\item\label{it:things-that-commute} Every isometry $\alpha$ that commutes with $\gamma$ leaves
0357 | 		$\mathrm{Min}(\gamma)=Y\times\bbR$ invariant, and its restriction
0358 | 		to $Y\times\bbR$ is of the form $(\alpha',\alpha'')$ where
0359 | 		$\alpha'$ is an isometry of $Y$ and $\alpha''$ is a translation of $\bbR$.
0360 | 	\end{enumerate}
0361 | \end{thm}
