0610 | \begin{defn}[Translation lengths]\label{defn:translation-lengths}
0611 |   Let $\churro$ be attached to the waffles in
0612 |   $\{\waffle_i\mid 1\leq i \leq m_\churro\}$ with strands
0613 |   $\waffle_i \cap \churro =\strand_i$. We have
0614 |   $\Gamma_\churro = \bk{h_\churro}$ which maps each $\strand_i$ to
0615 |   itself and we define the \define{strand translation
0616 |     lengths}:\[ \tau_{\strand_i} = d_{\waffle_i}(x,h_\churro x),
0617 |     \textrm{~for any~} x \in \strand_i\] where $d_{\waffle_i}$ is the
0618 |   standard unit edge length CAT(0) metric on $\waffle_i$. We further
0619 |   define the \define{core translation length} to be the average\[
0620 |     \tau_{\churrocore} = \frac{1}{m_\churro}\sum_{i=1}^{m_\churro}\tau_{\strand_i}
0621 |   .\]
0622 | \end{defn}
0623 | 
0624 | \begin{defn}[The churro metric]\label{defn:churro-metrization}
0625 |   Let $\churro$ be as described above, then the flap $\flap_{i}$
0626 |   connecting the core $\churrocore$ to the waffle $\waffle_i$ can be
0627 |   metrized as:
0628 |   \begin{enumerate}
0629 |   \item A horostrip of width
0630 |     \[\left|\ln\left(\frac{\tau_\churrocore}{\tau_{\strand_i}}\right)\right|\]
0631 |     with the long side identified with $\churrocore$ if
0632 |     $\tau_\churrocore > \tau_{\strand_i}$, or the long side identified
0633 |     with $\strand_i \subset \waffle_i$ if
0634 |     $\tau_\churrocore < \tau_{\strand_i}$; provided
0635 |     $\tau_\churrocore \neq \tau_{\strand_i}$.
0636 |   \item The Euclidean unit strip $\flap_{\bbE}=\{(x,y)\in \bbR^2 \mid
0637 |     0\leq y\leq 1$ equipped with the Euclidean $\bbE^2$-metric, if
0638 |     $\tau_\churrocore = \tau_{\strand_i}$.
0639 |   \end{enumerate}
0640 |   We then identify the sides of all the $\churrocore$ sides of the
0641 |   flaps so that the lengths of any arc $\alpha$ contained in
0642 |   $\churrocore$ coincide in ($\bbH^2$ or $\bbE^2$)-metric on each
0643 |   attached flap.
0644 | \end{defn}
