0729 | \subsubsection{The cell-complex structure on a churro-waffle space}
0730 | 
0731 | \begin{defn}[Strand subdivision]\label{defn:waffle-subdivision}
0732 |   Let $\waffle$ be a waffle, then a \define{strand subdivision} is a
0733 |   combinatorial subdivision of the cube complex $\waffle$ so that each
0734 |   strand lies inside the 1-skeleton of the subdivided waffle. The
0735 |   \define{waffle subdivision} of a strand is the simplicial structure
0736 |   on a strand induced by the strand subdivision of the ambient waffle.
0737 | \end{defn}
0738 | 
0739 | \begin{defn}[Flap subdivision, core and strand vertices]
0740 |   Let a waffle $\waffle$ be attached to a churro $\churro$ and if
0741 |   $\hat\waffle$ is a strand subdivision of $\waffle$ and $\hat\strand$
0742 |   is the corresponding waffle subdivision of the
0743 |   strand $\strand = \waffle \cap \churro$, then we subdivide the flap
0744 |   $\flap{}$ connecting $\strand$ and the churro core $\churrocore$ so
0745 |   that each vertical leaf $\ell$ containing a vertex of $\hat\strand$
0746 |   becomes a 1-cell called a \define{subdivision edge}. Extremities
0747 |   of these 1-cells in $\churrocore$ are called \define{core vertices}
0748 |   if they lie in the churro core, and \define{strand vertices} if they
0749 |   lie in a strand.
0750 | \end{defn}
0751 | 
0752 | \begin{defn}[Generalized Dehn twists]
0753 |   Consider the map $\alpha:Z \to \churrocore$ identifying a component
0754 |   of the boundary $Z \subset \partial \flap{}\subset \churro$ of a
0755 |   flap of churro $\churro$ to the churro core $\churrocore$. A
0756 |   \define{generalized Dehn twist} is the result of reattaching
0757 |   $\flap{}$ to $\churrocore$ via a $\Gamma$-equivariant post
0758 |   composition with a
0759 |   translation:\[ (t\mapsto t+\epsilon)\circ \alpha; \epsilon \in
0760 |     \mathbb R. \] An \define{equivariant generalized Dehn twist} of a
0761 |   churro-waffle space $\chuwaf\Xi$ is the result of
0762 |   $\aut{\chuwaf\Xi}$-equivariantly redefining the attaching maps of
0763 |   flaps to churro cores via generalized Dehn twists. If $D$ is a
0764 |   finite set of equivariant generalized Dehn twists, then denote the space
0765 |   obtained by successively applying these as \[ \chuwaf\Xi^D.\]
0766 | \end{defn}
0767 | 
0768 | \begin{lem}\label{lem:partial-twist}
0769 |   There is a $\Gamma$-equivariant quasi-isometry between
0770 |   $\chuwaf\Gamma$ and the result of finitely many equivariant
0771 |   generalized Dehn twist $D$, furthermore $\Gamma$ still acts on the
0772 |   resulting space $\chuwaf\Gamma^D$ by automorphisms. Also, given an
0773 |   equivariant strand subdivision of each waffle in $\chuwaf\Gamma$,
0774 |   equivariant generalized Dehn twists can only produce a finite number
0775 |   of distinct (up to isomorphism) flap subdivisions that minimize the
0776 |   number of $\Gamma$-orbits of core vertices.
0777 | \end{lem}
0778 | \begin{proof}
0779 |   $\Gamma$ acts freely on $\chuwaf\Gamma$ and is in bijective
0780 |   correspondence with homotopy classes of paths from some basepoint
0781 |   $b \in \chuwaf\Gamma$ not lying in a churro core and some other
0782 |   point $\gamma\cdot b \in \chuwaf\Gamma$ where $\gamma \in
0783 |   \Gamma$. Let $\rho$ be a path connecting $b$ and $\gamma\cdot b$. We
0784 |   can subdivide $\rho$ into
0785 |   \begin{equation}\label{eqn:rho-subdiv}
0786 |      \rho = \rho_1*\cdots*\rho_k
0787 |   \end{equation}
0788 |   where each $\rho_i$ is maximal with respect to containment with the
0789 |   property that the interior of $\rho_i$ is disjoint from the set of
0790 |   churro cores. Let $\delta$ be a generalized equivariant Dehn
0791 |   twist. Each subpath of $\rho$ given in (\ref{eqn:rho-subdiv}) has an
0792 |   image in the resulting space, the \define{push-forward of $\rho$} is
0793 |   the concatenation
0794 |   \[ \delta^*(\rho) = \rho_1*\mu_1*\cdots*\mu_{k-1}*\rho_k,
0795 |   \] where the $\mu_i$ are shortest paths contained in churro cores connecting the
0796 |   endpoints of the $\rho_{i}$ to $\rho_{i+1}$. It is a consequence of
0797 |   the definition of fundamental groups and covering spaces that in
0798 |   this way $\delta^*$ gives an action of $\Gamma$ by deck
0799 |   transformations, and by construction the path metric remains
0800 |   $\Gamma$-equivariant.
0801 | 
0802 |   Now note that the number of $\Gamma$ orbits of core vertices is
0803 |   minimized whenever the endpoints of different subdivision edges in
0804 |   different flaps coincide in $\churrocore$. Since $\Gamma$ acts
0805 |   cocompactly on $\chuwaf\Gamma$, there are only finitely many
0806 |   possible cellular decompositions of churros that can arise from
0807 |   generalized equivariant Dehn twists, up to automorphism.
0808 | \end{proof}
